css:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root{--bg:#ffffff;--text:#111114;--muted:#6b6b76;--primary:#6c3ce9;--primary-soft:#b9a3f5;--card:#f2f2f4;--dark:#000000;--radius:28px;--avatar-ring:#6c3ce9;}

.slide{font-family:'Plus Jakarta Sans',sans-serif;color:var(--text);background:var(--bg);padding:56px 64px;line-height:1.5;}

h1,h2,h3{font-family:'Plus Jakarta Sans',sans-serif;margin:0 0 .4em;letter-spacing:-0.02em;}
h1{font-size:64px;font-weight:800;color:var(--primary);line-height:1.05;}
h2{font-size:42px;font-weight:800;color:var(--text);line-height:1.1;}
h3{font-size:26px;font-weight:700;color:var(--text);line-height:1.2;margin-bottom:.5em;}

p{font-size:18px;font-weight:400;color:var(--text);margin:0 0 1em;}
.lead{font-size:30px;font-weight:700;color:var(--text);line-height:1.25;}
.muted{color:var(--muted);font-size:17px;font-weight:400;}
.eyebrow{text-transform:uppercase;font-size:13px;font-weight:700;letter-spacing:.12em;color:var(--primary);margin:0 0 .8em;}

.split{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center;height:100%;}
.stack{display:flex;flex-direction:column;gap:24px;}
.grid-cards{display:grid;grid-template-columns:1fr 1fr;gap:28px;}

.card{background:var(--card);border-radius:var(--radius);padding:32px 36px;box-shadow:0 8px 30px rgba(17,17,20,.05);}
.card--purple{background:var(--primary);color:#ffffff;}
.card--purple h3,.card--purple p,.card--purple .muted{color:#ffffff;}
.card--dark{background:var(--dark);color:#ffffff;}
.card--dark h3,.card--dark p,.card--dark .muted{color:#ffffff;}

.media{background:linear-gradient(160deg,#8a6cf0 0%,#6c3ce9 100%);background-size:cover;background-position:center;border-radius:var(--radius);min-height:320px;}
.media--dark{background:linear-gradient(160deg,#2a2a33 0%,#000000 100%);background-size:cover;background-position:center;}

.pill{display:inline-flex;align-items:center;gap:10px;background:var(--dark);color:#ffffff;border-radius:999px;padding:18px 40px;font-size:20px;font-weight:700;text-decoration:none;}

.tag{display:inline-block;background:var(--card);color:var(--muted);border-radius:16px;padding:18px 26px;font-size:17px;font-weight:500;}

.slide.section-divider{background:var(--primary);color:#ffffff;}
.slide.section-divider h1,.slide.section-divider h2,.slide.section-divider h3{color:#ffffff;}
.slide.section-divider .eyebrow{color:rgba(255,255,255,.8);}

.slide.outro{background:var(--dark);color:#ffffff;}
.slide.outro h1{color:var(--primary-soft);}
.slide.outro p,.slide.outro .lead{color:#ffffff;}
.slide.outro .muted{color:rgba(255,255,255,.7);}
